              />
            </div>
          </div>
        ) : null}

        {footnote ? (
          <div className="mt-10 max-w-prose border-t border-border pt-4 text-sm leading-relaxed text-muted-foreground">
            {footnote}
          </div>
        ) : null}
      </div>
    </div>
  );
}

/**
 * A horizontal bar chart that is also its own text alternative: a table with
 * one row per period, the value written out beside each bar.
 */
function TrendChart({
  trend,
  loading,
  headingId,
  descriptionId,
  Heading,
}: {
  trend: DashboardTrend;
  loading: boolean;
  headingId: string;
  descriptionId: string;
  Heading: "h2" | "h3";
}) {
  const {
    title,
    description,
    periodHeading = "Week",
    valueHeading,
    points,
    unit = "%",
    target,
  } = trend;
  const max = trend.max ?? 100;
  const percent = (value: number) =>
    `${Math.min(100, Math.max(0, (value / max) * 100))}%`;

  return (
    <section aria-labelledby={headingId}>
      <Heading
        id={headingId}
        className="text-lg leading-snug font-semibold tracking-tight text-balance"
      >
        {title}
      </Heading>
      {loading ? (
        <span aria-hidden="true" className={cn(skeleton, "mt-2 h-5 w-3/4")} />
      ) : description ? (
        <p
          id={descriptionId}
          className="mt-1 max-w-prose text-sm leading-relaxed text-muted-foreground"
        >
          {description}
        </p>
      ) : null}

      <table
        aria-labelledby={headingId}
        aria-describedby={!loading && description ? descriptionId : undefined}
        className="mt-4 w-full border-collapse text-sm"
      >
        <thead>
          <tr className="border-b border-border text-left text-muted-foreground">
            <th scope="col" className="py-2 pr-3 font-medium">
              {periodHeading}
            </th>
            <th scope="col" className="py-2 text-right font-medium">
              {valueHeading}
            </th>
          </tr>
        </thead>
        <tbody>
          {points.map((point) => (
            <tr key={point.label}>
              <th
                scope="row"
                className={cn(
                  "w-px py-1.5 pr-3 text-left whitespace-nowrap",
                  point.current ? "font-semibold" : "font-normal",
                )}
              >
                {point.label}
              </th>
              <td className="py-1.5">
                <span className="flex items-center gap-3">
                  <span
                    aria-hidden="true"
                    className="relative block h-4 min-w-0 flex-1 rounded-sm bg-muted"
                  >
                    {loading ? null : (
                      <span
                        className={cn(
                          "absolute inset-y-0 left-0 block rounded-sm",
                          point.current
                            ? "bg-foreground"
                            : "bg-muted-foreground",
                        )}
                        style={{ width: percent(point.value) }}
                      />
                    )}
                    {target ? (
                      <span
                        className="absolute -inset-y-1.5 block border-l-2 border-dashed border-foreground"
                        style={{ left: percent(target.value) }}
                      />
                    ) : null}
                  </span>
                  <span
                    className={cn(
                      "w-12 shrink-0 text-right tabular-nums",
                      point.current && "font-semibold",
                    )}
                  >
                    {loading ? (
                      <span
                        aria-hidden="true"
                        className={cn(skeleton, "ml-auto h-5 w-9")}
                      />
                    ) : (
                      (point.display ?? `${point.value}${unit}`)
                    )}
                  </span>
                </span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {target ? (
        <p className="mt-3 flex items-center gap-2 text-sm text-muted-foreground">
          <svg
            aria-hidden="true"
            viewBox="0 0 4 20"
            className="h-5 w-1 shrink-0 text-foreground"
          >
            <line
              x1="2"
              y1="0"
              x2="2"
              y2="20"
              stroke="currentColor"
              strokeWidth="2"
              strokeDasharray="4 3"
            />
          </svg>
          <span>{target.label}</span>
        </p>
      ) : null}
    </section>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/registry/shadcn/lib/utils";
import { Button } from "@/registry/shadcn/ui/button";

type HeadingLevel = 2 | 3 | 4;
type CellValue = string | number | null;
type SortDirection = "ascending" | "descending";

export type DataTableColumn = {
  /** Key into each row's `values`. */
  key: string;
  /** Header text. Short nouns: "Status", "Words", "Updated". */
  label: string;
  /**
   * `text` sorts alphabetically; `number` right-aligns in tabular figures;
   * `date` takes an ISO date ("2026-09-14") and formats it for `locale`.
   */
  type?: "text" | "number" | "date";
  /** Adds a sort button to the header. */
  sortable?: boolean;
};

export type DataTableRow = {
  /** Stable id: used as the React key. */
  id: string;
  /** Where the row's first cell links to. Omit for rows with no detail page. */
  href?: string;
  values: Record<string, CellValue>;
};

export type DataTableMessage = {
  /** Says what happened, in the user's words: "No notes in Field research yet". */
  title: React.ReactNode;
  /** Why, what is safe, and what will appear here. */
  description?: React.ReactNode;
  /** One next step. In the error state, the retry. */
  action?: React.ReactNode;
};

export type DataTableProps = Omit<React.ComponentProps<"section">, "title"> & {
  /** Names the data, not the widget: "Notes in Field research". */
  title: React.ReactNode;
  description?: React.ReactNode;
  headingLevel?: HeadingLevel;
  /** The page's one primary action for this data, e.g. "New note". */
  actions?: React.ReactNode;
  /** The first column is the row header; it links to `row.href` and stays in view when the table scrolls sideways. */
  columns: DataTableColumn[];
  rows: DataTableRow[];
  /** What a row is, for the result count: { one: "note", other: "notes" }. */
  noun: { one: string; other: string };
  /** `loading` keeps the layout with placeholder rows; `error` replaces the rows with `error`. */
  status?: "ready" | "loading" | "error";
  /** Column keys the search box matches, and how to describe them. */
  search: { keys: string[]; label: string; scope: string };
  /**
   * One column to filter by. `options` sets their order (for example the
   * order a status moves through); without it, the column's distinct values
   * are listed alphabetically.
   */
  filter?: { key: string; label: string; allLabel: string; options?: string[] };
  defaultSort?: { key: string; direction: SortDirection };
  defaultQuery?: string;
  defaultFilter?: string;
  /** First use: there are no rows at all. */
  empty: DataTableMessage;
  /** Loading failed. Say what failed and what is still safe; offer a retry. */
  error?: DataTableMessage;
  /** Shown before the error title so the state never relies on colour. */
  errorLabel?: string;
  locale?: string;
  /** Placeholder rows while loading. Match a typical page so nothing jumps. */
  loadingRows?: number;
};

function formatCell(
  value: CellValue,
  type: DataTableColumn["type"],
  locale: string,
) {
  if (value === null || value === "") return "—";
  if (type === "number" && typeof value === "number") {
    return new Intl.NumberFormat(locale).format(value);
  }
  if (type === "date" && typeof value === "string") {
    const date = new Date(`${value}T00:00:00Z`);
    if (Number.isNaN(date.getTime())) return value;
    return new Intl.DateTimeFormat(locale, {
      day: "numeric",
      month: "short",
      year: "numeric",
      timeZone: "UTC",
    }).format(date);
  }
  return String(value);
}

function compareValues(a: CellValue, b: CellValue, locale: string) {
  // Empty values sort last in both directions; the caller flips the rest.
  if (typeof a === "number" && typeof b === "number") return a - b;
  return String(a).localeCompare(String(b), locale, { numeric: true });
}

function SortIcon({ direction }: { direction?: SortDirection }) {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      className={cn(
        "size-3.5 shrink-0",
        direction ? "text-foreground" : "text-muted-foreground",
      )}
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {direction !== "descending" ? <path d="M5 6.5 8 3.5l3 3" /> : null}
      {direction !== "ascending" ? <path d="m5 9.5 3 3 3-3" /> : null}
    </svg>
  );
}

export function DataTable({
  title,
  description,
  headingLevel = 2,
  actions,
  columns,
  rows,
  noun,
  status = "ready",
  search,
  filter,
  defaultSort,
  defaultQuery = "",
  defaultFilter = "",
  empty,
  error,
  errorLabel = "Error",
  locale = "en-US",
  loadingRows = 6,
  className,
  ...props
}: DataTableProps) {
  const id = React.useId();
  const headingId = `${id}-heading`;
  const searchId = `${id}-search`;
  const filterId = `${id}-filter`;
  const Heading = `h${headingLevel}` as const;
  const MessageHeading = `h${Math.min(headingLevel + 1, 6)}` as "h3";

  const [query, setQuery] = React.useState(defaultQuery);
  const [filterValue, setFilterValue] = React.useState(defaultFilter);
  const [sort, setSort] = React.useState(defaultSort);
  const searchRef = React.useRef<HTMLInputElement>(null);

  // Show a scroll hint and make the region focusable only when the table is
  // wider than its container.
  const scrollRef = React.useRef<HTMLDivElement>(null);
  const [overflowing, setOverflowing] = React.useState(false);
  React.useEffect(() => {
    const element = scrollRef.current;
    if (!element || typeof ResizeObserver === "undefined") return;
    const measure = () =>
      setOverflowing(element.scrollWidth > element.clientWidth + 1);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  const filterOptions = React.useMemo(() => {
    if (!filter) return [];
    if (filter.options) return filter.options;
    const seen = new Set<string>();
    for (const row of rows) {
      const value = row.values[filter.key];
      if (value !== null && value !== "") seen.add(String(value));
    }
    return [...seen].sort((a, b) => a.localeCompare(b, locale));
  }, [filter, rows, locale]);

  const visibleRows = React.useMemo(() => {
    const needle = query.trim().toLocaleLowerCase(locale);
    const matching = rows.filter((row) => {
      if (
        filter &&
        filterValue &&
        String(row.values[filter.key]) !== filterValue
      ) {
        return false;
      }
      if (!needle) return true;
      return search.keys.some((key) =>
        String(row.values[key] ?? "")
          .toLocaleLowerCase(locale)
          .includes(needle),
      );
    });
    if (!sort) return matching;
    const flip = sort.direction === "ascending" ? 1 : -1;
    return [...matching].sort((a, b) => {
      const left = a.values[sort.key] ?? null;
      const right = b.values[sort.key] ?? null;
      if (left === null || right === null) {
        return left === right ? 0 : left === null ? 1 : -1;
      }
      return compareValues(left, right, locale) * flip;
    });
  }, [rows, query, filter, filterValue, search.keys, sort, locale]);

  const isLoading = status === "loading";
  const isError = status === "error";
  const isEmpty = status === "ready" && rows.length === 0;
  const isFiltered = query.trim() !== "" || filterValue !== "";
  const noResults =
    status === "ready" && rows.length > 0 && visibleRows.length === 0;
  const controlsDisabled = isLoading || isError || isEmpty;

  const countText = isLoading
    ? `Loading ${noun.other}…`
    : isError
      ? `${noun.other.charAt(0).toUpperCase()}${noun.other.slice(1)} didn’t load`
      : isEmpty
        ? `No ${noun.other} yet`
        : isFiltered
          ? `Showing ${visibleRows.length} of ${rows.length} ${rows.length === 1 ? noun.one : noun.other}`
          : `${rows.length} ${rows.length === 1 ? noun.one : noun.other}`;

  function clearFilters() {
    setQuery("");
    setFilterValue("");
    // The button that was focused disappears; put focus somewhere useful.
    searchRef.current?.focus();
  }

  function toggleSort(key: string) {
    setSort((current) =>
      current?.key === key && current.direction === "ascending"
        ? { key, direction: "descending" }
        : { key, direction: "ascending" },
    );
  }

  const filterDescription =
    filter && filterValue ? `${filter.label}: ${filterValue}` : "";

  const message: (DataTableMessage & { kind: string }) | null = isError
    ? {
        kind: "error",
        title: error?.title ?? countText,
        description: error?.description,
        action: error?.action,
      }
    : isEmpty
      ? { kind: "empty", ...empty }
      : noResults
        ? {
            kind: "no-results",
            title: query.trim() ? (
              <>
                No {noun.other} match <q>{query.trim()}</q>
              </>
            ) : (
              `No ${noun.other} match these filters`
            ),
            description: `Search covers ${search.scope}${
              filterDescription ? `, filtered to ${filterDescription}` : ""
            }. Check the spelling or clear the filters to see all ${rows.length} ${noun.other}.`,
            action: (
              <Button
                type="button"
                variant="outline"
                size="lg"
                className="h-11 w-full px-5 sm:w-auto"
                onClick={clearFilters}
              >
                Clear search and filters
              </Button>
            ),
          }
        : null;

  const cellBase = "border-b border-border px-3 text-left align-middle";
  const stickyCell =
    "sticky left-0 z-10 group-data-[overflowing=true]/table:border-r";

  return (
    <section
      aria-labelledby={headingId}
      data-slot="data-table"
      data-status={status}
      className={cn("text-foreground", className)}
      {...props}
    >
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div className="max-w-prose">
          <Heading
            id={headingId}
            className="text-2xl leading-tight font-semibold tracking-tight text-balance"
          >
            {title}
          </Heading>
          {description ? (
            <p className="mt-2 text-sm leading-relaxed text-pretty text-muted-foreground">
              {description}
            </p>
          ) : null}
        </div>
        {actions ? (
          <div className="flex shrink-0 flex-col gap-3 sm:flex-row">
            {actions}
          </div>
        ) : null}
      </div>

      <form
        role="search"
        aria-label={`Filter ${noun.other}`}
        onSubmit={(event) => event.preventDefault()}
        className="mt-6 grid gap-3 sm:grid-cols-[minmax(0,20rem)_minmax(0,12rem)] sm:items-end"
      >
        <div className="grid gap-1.5">
          <label htmlFor={searchId} className="text-sm font-medium">
            {search.label}
          </label>
          <input
            ref={searchRef}
            id={searchId}
            type="search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            disabled={controlsDisabled}
            autoComplete="off"
            className="h-11 w-full rounded-md border border-input bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-50"
          />
        </div>
        {filter ? (
          <div className="grid gap-1.5">
            <label htmlFor={filterId} className="text-sm font-medium">
              {filter.label}
            </label>
            <select
              id={filterId}
              value={filterValue}
              onChange={(event) => setFilterValue(event.target.value)}
              disabled={controlsDisabled}
              className="h-11 w-full rounded-md border border-input bg-background px-3 text-sm text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-50"
            >
              <option value="">{filter.allLabel}</option>
              {filterOptions.map((option) => (
                <option key={option} value={option}>
                  {option}
                </option>
              ))}
            </select>
          </div>
        ) : null}
      </form>

      <p
        role="status"
        aria-live="polite"
        className="mt-4 min-h-5 text-sm text-muted-foreground tabular-nums"
      >
        {countText}
      </p>

      <div
        data-overflowing={overflowing}
        className="group/table mt-2 overflow-hidden rounded-lg border border-border bg-card text-card-foreground"
      >
        <div
          ref={scrollRef}
          role={overflowing ? "region" : undefined}
          aria-label={
            overflowing ? `Table of ${noun.other}, scrolls sideways` : undefined
          }
          tabIndex={overflowing ? 0 : undefined}
          className="overflow-x-auto focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none focus-visible:ring-inset"
        >
          <table
            aria-labelledby={headingId}
            aria-busy={isLoading || undefined}
            className="w-full min-w-[40rem] border-separate border-spacing-0 text-sm"
          >
            <thead>
              <tr>
                {columns.map((column, index) => {
                  const numeric = column.type === "number";
                  const direction =
                    sort?.key === column.key ? sort.direction : undefined;
                  return (
                    <th
                      key={column.key}
                      scope="col"
                      aria-sort={direction}
                      className={cn(
                        cellBase,
                        "h-11 bg-muted py-0 font-medium whitespace-nowrap text-muted-foreground",
                        numeric && "text-right",
                        index === 0 && stickyCell,
                      )}
                    >
                      {column.sortable ? (
                        <button
                          type="button"
                          onClick={() => toggleSort(column.key)}
                          disabled={controlsDisabled}
                          className={cn(
                            "-mx-2 inline-flex min-h-11 items-center gap-1.5 rounded-sm px-2 font-medium outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-default disabled:hover:text-muted-foreground",
                            numeric && "flex-row-reverse",
                            direction && "text-foreground",
                          )}
                        >
                          {column.label}
                          <SortIcon direction={direction} />
                        </button>
                      ) : (
                        column.label
                      )}
                    </th>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {isLoading
                ? Array.from({ length: loadingRows }, (_, rowIndex) => (
                    <tr key={rowIndex} aria-hidden="true">
                      {columns.map((column, index) => (
                        <td
                          key={column.key}
                          className={cn(
                            cellBase,
                            "h-11 bg-card",
                            index === 0 && stickyCell,
                            rowIndex === loadingRows - 1 && "border-b-0",
                          )}
                        >
                          <span
                            className={cn(
                              "block h-3 rounded-sm bg-accent",
                              column.type === "number" && "ml-auto",
                              index === 0
                                ? ["w-4/5", "w-3/5", "w-2/3"][rowIndex % 3]
                                : "w-16",
                            )}
                          />
                        </td>
                      ))}
                    </tr>
                  ))
                : message
                  ? null
                  : visibleRows.map((row, rowIndex) => (
                      <tr key={row.id}>
                        {columns.map((column, index) => {
                          const value = formatCell(
                            row.values[column.key] ?? null,
                            column.type,
                            locale,
                          );
                          const last = rowIndex === visibleRows.length - 1;
                          const classes = cn(
                            cellBase,
                            "h-11 bg-card py-1.5",
                            column.type === "number" &&
                              "text-right tabular-nums",
                            column.type === "date" &&
                              "whitespace-nowrap tabular-nums",
                            last && "border-b-0",
                          );
                          if (index === 0) {
                            return (
                              <th
                                key={column.key}
                                scope="row"
                                className={cn(
                                  classes,
                                  stickyCell,
                                  "min-w-40 py-0 font-medium sm:min-w-56",
                                )}
                              >
                                {row.href ? (
                                  <a
                                    href={row.href}
                                    className="-mx-1 inline-flex min-h-11 items-center rounded-sm px-1 underline-offset-4 outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/50"
                                  >
                                    {value}
                                  </a>
                                ) : (
                                  value
                                )}
                              </th>
                            );
                          }
                          return (
                            <td
                              key={column.key}
                              className={cn(
                                classes,
                                "whitespace-nowrap",
                                column.type === undefined ||
                                  column.type === "text"
                                  ? "text-muted-foreground"
                                  : null,
                              )}
                            >
                              {value}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
            </tbody>
          </table>
        </div>

        {message ? (
          <div data-message={message.kind} className="px-4 py-8 sm:px-6">
            <div className="max-w-prose">
              <MessageHeading className="text-base leading-snug font-semibold text-balance">
                {message.kind === "error" ? (
                  <span className="mb-1 block text-sm font-semibold text-destructive">
                    {errorLabel}
                  </span>
                ) : null}
                {message.title}
              </MessageHeading>
              {message.description ? (
                <div className="mt-2 text-sm leading-relaxed text-pretty text-muted-foreground">
                  {message.description}
                </div>
              ) : null}
            </div>
            {message.action ? (
              <div className="mt-5 flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center">
                {message.action}
              </div>
            ) : null}
          </div>
        ) : null}
      </div>

      <p
        aria-hidden="true"
        className={cn(
          "mt-2 text-sm text-muted-foreground",
          overflowing && !message ? "block" : "hidden",
        )}
      >
        Scroll the table sideways to see every column.
      </p>
    </section>
  );
}

import * as React from "react";

import { cn } from "@/registry/shadcn/lib/utils";

type HeadingLevel = 2 | 3 | 4;

export type EmptyStateProps = Omit<React.ComponentProps<"section">, "title"> & {
  /** Says what is empty, in the user's words: "No notes in Field research yet". */
  title: React.ReactNode;
  /** One or two sentences: why it is empty and what will appear here. */
  description?: React.ReactNode;
  /**
   * `neutral` for first use and no results; `error` when something failed.
   * Error adds a text label, so the state never relies on colour alone.
   */
  variant?: "neutral" | "error";
  /** Text shown before the title in the error variant. */
  errorLabel?: string;
  /** Match the surrounding outline; the empty state replaces a region's content. */
  headingLevel?: HeadingLevel;
  /** Actions: one primary, at most one secondary. */
  actions?: React.ReactNode;
};

export function EmptyState({
  title,
  description,
  variant = "neutral",
  errorLabel = "Error",
  headingLevel = 2,
  actions,
  children,
  className,
  ...props
}: EmptyStateProps) {
  const headingId = React.useId();
  const Heading = `h${headingLevel}` as const;
  const isError = variant === "error";

  return (
    <section
      aria-labelledby={headingId}
      data-slot="empty-state"
      data-variant={variant}
      className={cn(
        "rounded-lg border bg-card px-5 py-6 text-card-foreground sm:px-8 sm:py-8",
        isError ? "border-destructive/50" : "border-dashed border-border",
        className,
      )}
      {...props}
    >
      <div className="max-w-prose">
        <Heading
          id={headingId}
          className="text-lg leading-snug font-semibold tracking-tight text-balance"
        >
          {isError ? (
            <span className="mb-1 block text-sm font-semibold text-destructive">
              {errorLabel}
            </span>
          ) : null}
          {title}
        </Heading>
        {description ? (
          <div className="mt-2 text-sm leading-relaxed text-pretty text-muted-foreground">
            {description}
          </div>
        ) : null}
        {children ? <div className="mt-4 text-sm">{children}</div> : null}
      </div>
      {actions ? (
        <div className="mt-6 flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center">
          {actions}
        </div>
      ) : null}
    </section>
  );
}

import * as React from "react";

import { cn } from "@/registry/shadcn/lib/utils";

export type FaqItem = {
  /** The question as a buyer would ask it, not a marketing prompt. */
  question: string;
  /** A direct answer first, then the detail. Keep it to a few sentences. */
  answer: React.ReactNode;
};

export type FaqProps = Omit<React.ComponentProps<"section">, "title"> & {
  title: React.ReactNode;
  /** One sentence on what these questions cover. */
  description?: React.ReactNode;
  items: FaqItem[];
  /** Where to go when the answer is not here: a real contact route. */
  contact?: React.ReactNode;
  /** Open the first answer on load. Off by default. */
  openFirst?: boolean;
};

export function Faq({
  title,
  description,
  items,
  contact,
  openFirst = false,
  className,
  ...props
}: FaqProps) {
  const headingId = React.useId();

  return (
    <section
      aria-labelledby={headingId}
      data-slot="faq"
      className={cn("bg-background text-foreground", className)}
      {...props}
    >
      <div className="mx-auto grid w-full max-w-6xl gap-8 px-4 py-12 sm:px-6 sm:py-16 lg:grid-cols-[minmax(0,1fr)_minmax(0,2fr)] lg:gap-16 lg:px-8 lg:py-24">
        <div className="lg:sticky lg:top-8 lg:self-start">
          <h2
            id={headingId}
            className="text-3xl leading-tight font-semibold tracking-tight text-balance sm:text-4xl"
          >
            {title}
          </h2>
          {description ? (
            <p className="mt-4 max-w-prose text-base leading-relaxed text-pretty text-muted-foreground">
              {description}
            </p>
          ) : null}
          {contact ? (
            <div className="mt-6 max-w-prose text-sm leading-relaxed text-muted-foreground">
              {contact}
            </div>
          ) : null}
        </div>

        <div className="border-t border-border">
          {items.map((item, index) => (
            <details
              key={item.question}
              open={openFirst && index === 0}
              className="group border-b border-border"
            >
              <summary className="flex min-h-11 cursor-pointer list-none items-start justify-between gap-4 rounded-sm py-4 text-left text-base leading-snug font-medium focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none [&::-webkit-details-marker]:hidden">
                <span>{item.question}</span>
                <svg
                  aria-hidden="true"
                  viewBox="0 0 16 16"
                  className="mt-1 size-4 shrink-0 text-muted-foreground transition-transform duration-200 group-open:rotate-45 motion-reduce:transition-none"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                >
                  <path d="M8 3v10M3 8h10" />
                </svg>
              </summary>
              <div className="max-w-prose pr-8 pb-5 text-sm leading-relaxed text-pretty text-muted-foreground">
                {item.answer}
              </div>
            </details>
          ))}
        </div>
      </div>
    </section>
  );
}

import * as React from "react";

import { cn } from "@/registry/shadcn/lib/utils";

export type FeatureFact = {
  /** What is limited or guaranteed: "History kept on Team". */
  label: string;
  /** The exact value, written out: "1 year", not a tick. */
  value: React.ReactNode;
};

export type EvidenceFeature = {
  id: string;
  /** A claim the artefact can prove, not an adjective ("Every edit is kept"). */
  title: React.ReactNode;
  /** Two or three sentences: what it does and the one condition that matters. */
  description: React.ReactNode;
  /**
   * The proof: a small UI fragment, a before/after or an exact limit. Use
   * EvidencePanel, BeforeAfter or ExactLimits below, or your own markup.
   * Never an icon standing in for the feature.
   */
  evidence: React.ReactNode;
  /** One sentence saying what the artefact shows. Rendered as its caption. */
  evidenceCaption: React.ReactNode;
  /** Exact limits or guarantees, in the order a buyer would check them. */
  facts?: FeatureFact[];
  /** Where to read more. The label names the destination. */
  link?: { label: string; href: string };
};

export type FeatureEvidenceProps = Omit<
  React.ComponentProps<"section">,
  "title"
> & {
  /** The point of the section, not "Features". */
  title: React.ReactNode;
  description?: React.ReactNode;
  /** The feature that matters most. It gets the most room and a bigger heading. */
  lead: EvidenceFeature;
  /** One or two features that matter less than the lead, each with its own proof. */
  supporting?: EvidenceFeature[];
  /** Smaller features that need a sentence, not a showcase. Shown as a list. */
  more?: {
    title: React.ReactNode;
    items: { term: string; detail: React.ReactNode }[];
  };
  /** Anything a reader must know about the claims, such as plan limits. */
  footnote?: React.ReactNode;
};

function FeatureText({
  feature,
  emphasis,
}: {
  feature: EvidenceFeature;
  emphasis: "lead" | "supporting";
}) {
  const isLead = emphasis === "lead";
  return (
    <div className="min-w-0">
      <h3
        className={cn(
          "font-semibold tracking-tight text-balance",
          isLead ? "text-xl leading-snug" : "text-base leading-snug",
        )}
      >
        {feature.title}
      </h3>
      <div
        className={cn(
          "mt-3 max-w-prose leading-relaxed text-pretty text-muted-foreground",
          isLead ? "text-base" : "text-sm",
        )}
      >
        {feature.description}
      </div>
      {feature.facts?.length ? (
        <dl className="mt-6 max-w-prose border-t border-border text-sm">
          {feature.facts.map((fact) => (
            <div
              key={fact.label}
              className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1 border-b border-border py-3"
            >
              <dt className="text-muted-foreground">{fact.label}</dt>
              <dd className="font-medium tabular-nums">{fact.value}</dd>
            </div>
          ))}
        </dl>
      ) : null}
      {feature.link ? (
        <a
          href={feature.link.href}
          className="mt-4 inline-flex min-h-11 items-center rounded-sm text-sm font-medium text-foreground underline underline-offset-4 focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-none"
        >
          {feature.link.label}
        </a>
      ) : null}
    </div>
  );
}

function FeatureFigure({ feature }: { feature: EvidenceFeature }) {
  return (
    <figure className="min-w-0">
      {feature.evidence}
      <figcaption className="mt-3 text-sm leading-relaxed text-muted-foreground">
        {feature.evidenceCaption}
      </figcaption>
    </figure>
  );
}

/** Text beside its proof on wide screens; text first, then proof, on phones. */
function FeatureRow({
  feature,
  emphasis,
}: {
  feature: EvidenceFeature;
  emphasis: "lead" | "supporting";
}) {
  return (
    <div className="grid gap-8 lg:grid-cols-[minmax(0,5fr)_minmax(0,7fr)] lg:gap-12">
      <FeatureText feature={feature} emphasis={emphasis} />
      <FeatureFigure feature={feature} />
    </div>
  );
}

export function FeatureEvidence({
  title,
  description,
  lead,
  supporting = [],
  more,
  footnote,
  className,
  ...props
}: FeatureEvidenceProps) {
  const headingId = React.useId();

  return (
    <section
      aria-labelledby={headingId}
      data-slot="feature-evidence"
      className={cn("bg-background text-foreground", className)}
      {...props}
    >
      <div className="mx-auto w-full max-w-6xl px-4 py-12 sm:px-6 sm:py-16 lg:px-8 lg:py-24">
        <div className="max-w-2xl">
          <h2
            id={headingId}
            className="text-3xl leading-tight font-semibold tracking-tight text-balance sm:text-4xl"
          >
            {title}
          </h2>
          {description ? (
            <p className="mt-4 text-base leading-relaxed text-pretty text-muted-foreground">
              {description}
            </p>
          ) : null}
        </div>

        <div className="mt-10 border-t border-border pt-10 lg:mt-14">
          <FeatureRow feature={lead} emphasis="lead" />
        </div>

        {supporting.length === 1 ? (
          <div className="mt-12 border-t border-border pt-10">
            <FeatureRow feature={supporting[0]} emphasis="supporting" />
          </div>
        ) : supporting.length > 1 ? (
          <div className="mt-12 grid gap-12 border-t border-border pt-10 md:grid-cols-2 md:gap-8 lg:gap-12">
            {supporting.map((feature) => (
              <div key={feature.id} className="flex min-w-0 flex-col gap-6">
                <FeatureText feature={feature} emphasis="supporting" />
                <FeatureFigure feature={feature} />
              </div>
            ))}
          </div>
        ) : null}

        {more?.items.length ? (
          <div className="mt-12 border-t border-border pt-10">
            <h3 className="text-base leading-snug font-semibold tracking-tight">
              {more.title}
            </h3>
            <dl
              className={cn(
                "mt-4 grid gap-x-8 gap-y-5",
                // Three per row only when the count divides evenly, so no
                // item is left alone on the last row.
                more.items.length % 3 === 0
                  ? "md:grid-cols-3"
                  : "md:grid-cols-2",
              )}
            >
              {more.items.map((item) => (
                <div key={item.term} className="min-w-0">
                  <dt className="text-sm font-medium">{item.term}</dt>
                  <dd className="mt-1 max-w-prose text-sm leading-relaxed text-muted-foreground">
                    {item.detail}
                  </dd>
                </div>
              ))}
            </dl>
          </div>
        ) : null}

        {footnote ? (
          <div className="mt-10 max-w-prose text-sm leading-relaxed text-muted-foreground">
            {footnote}
          </div>
        ) : null}
      </div>
    </section>
  );
}

